import { app } from 'electron';
import fs from 'fs';
import path from 'path';
import os from 'os';
import child_process from 'child_process';
import { Logger } from '../logger';

const logger = Logger('appimage-desktop');

/**
 * AppImage 桌面集成（应用菜单入口 + 图标）
 *
 * 背景：AppImage 格式无安装过程，无法像 deb 那样声明依赖与注册桌面入口，
 * 此处采用 AppImage 生态的标准做法——应用首启时自注册（幂等）。
 *
 * - 运行于 AppImage（process.env.APPIMAGE 存在）：注册/更新 desktop entry 与图标
 * - 运行于非 AppImage（deb/开发模式）：若存在本应用自注册且 Exec 目标已失效的入口，清理之
 * - 标识约定：自注册文件含 X-OCS-AutoGenerated 标记，清理只触碰带标记的文件，
 *   不会误删 deb 包管理器安装的入口（/usr/share/applications 下的无标记文件）
 */

const MARKER = 'X-OCS-AutoGenerated';
const DESKTOP_FILENAME = 'ocs-desktop.desktop';
const ICON_NAME = 'ocs-desktop.png';

function desktopFilePath() {
	return path.join(os.homedir(), '.local', 'share', 'applications', DESKTOP_FILENAME);
}

function iconTargetPath() {
	return path.join(os.homedir(), '.local', 'share', 'icons', 'hicolor', '256x256', 'apps', ICON_NAME);
}

/** 刷新桌面数据库（存在才调用，失败不影响） */
function updateDesktopDatabase() {
	child_process.exec(`update-desktop-database "${path.dirname(desktopFilePath())}"`, () => {});
}

export function integrateAppImageDesktop() {
	if (process.platform !== 'linux') return;

	const desktopPath = desktopFilePath();
	const appImagePath = process.env.APPIMAGE;

	// ── 非 AppImage 运行：清理失效的自注册入口 ──
	if (!appImagePath) {
		try {
			if (!fs.existsSync(desktopPath)) return;
			const content = fs.readFileSync(desktopPath, 'utf-8');
			if (!content.includes(MARKER)) return; // 非本应用自注册，不动
			const execTarget = /^Exec="?([^"\n]+?)"?$/m.exec(content)?.[1];
			if (execTarget && !fs.existsSync(execTarget)) {
				fs.rmSync(desktopPath, { force: true });
				fs.rmSync(iconTargetPath(), { force: true });
				updateDesktopDatabase();
				logger.info('检测到失效的 AppImage 桌面入口，已清理');
			}
		} catch (e) {
			logger.warn('桌面入口清理失败', e);
		}
		return;
	}

	// ── AppImage 运行：注册/更新入口与图标（幂等：内容一致则跳过） ──
	try {
		const desktopContent = [
			'[Desktop Entry]',
			'Name=OCS Desktop',
			'Comment=OCS 浏览器自动化神器，一键浏览器多开，用户脚本环境一键配置。',
			// desktop entry 规范：路径含空格需双引号包裹
			`Exec="${appImagePath}"`,
			'Icon=ocs-desktop',
			'Type=Application',
			'Terminal=false',
			'Categories=Utility;',
			'StartupWMClass=OCS Desktop',
			`${MARKER}=true`,
			''
		].join('\n');

		const outdated = !fs.existsSync(desktopPath) || fs.readFileSync(desktopPath, 'utf-8') !== desktopContent;
		if (outdated) {
			fs.mkdirSync(path.dirname(desktopPath), { recursive: true });
			fs.writeFileSync(desktopPath, desktopContent, { mode: 0o755 });
		}

		// 图标：app 目录下 public/icons/256.png（asar:false 布局直接可读）
		const iconSource = path.join(app.getAppPath(), 'public', 'icons', '256.png');
		const iconTarget = iconTargetPath();
		if (fs.existsSync(iconSource)) {
			const iconOutdated = !fs.existsSync(iconTarget) || fs.statSync(iconSource).size !== fs.statSync(iconTarget).size;
			if (iconOutdated) {
				fs.mkdirSync(path.dirname(iconTarget), { recursive: true });
				fs.copyFileSync(iconSource, iconTarget);
			}
		}

		if (outdated) {
			updateDesktopDatabase();
			logger.info('AppImage 桌面入口已注册/更新');
		}
	} catch (e) {
		logger.warn('AppImage 桌面集成失败', e);
	}
}
